# Written by backend/scripts/homebrew_formula.cjs in the Seayora repository, from
# the packages seayora.com serves. Run that script; do not edit this file by hand.
class Seabridge < Formula
  desc "Connects cameras and building equipment on a property's network to Seayora"
  homepage "https://seayora.com/download/bridge"
  version "1.8.0"
  license :cannot_represent

  on_macos do
    on_arm do
      url "https://seayora.com/api/cameras/bridge/download/seayora-bridge-1.8.0-darwin-arm64.tar.gz", using: :nounzip
      sha256 "1aea797c64e450099d5914de725054126d10e4fcb936b4ac3d3bee8d65f8de6c"
    end
    on_intel do
      url "https://seayora.com/api/cameras/bridge/download/seayora-bridge-1.8.0-darwin-x64.tar.gz", using: :nounzip
      sha256 "8577e857c0846bb39087526fa7912a15d50476ec55f5e02f1af26ef083e1e586"
    end
  end

  on_linux do
    on_arm do
      url "https://seayora.com/api/cameras/bridge/download/seayora-bridge-1.8.0-linux-arm64.tar.gz", using: :nounzip
      sha256 "1f866a42e3262b7347888204134605bec39f8e00743bcb3897705624c21abf81"
    end
    on_intel do
      url "https://seayora.com/api/cameras/bridge/download/seayora-bridge-1.8.0-linux-x64.tar.gz", using: :nounzip
      sha256 "249087904b0d0bfc8162a3c684e3cce7d0d52837d5c47c0492021309026d2bd9"
    end
  end

  WRAPPER = <<~'SH'.freeze
    #!/bin/sh
    # seabridge: the Seayora Bridge, installed with Homebrew.
    #
    #   seabridge ABCD-2345       install the bridge on this computer and pair it
    #   seabridge --pair-later    install it now; pair it later: seabridge pair ABCD-2345
    #   seabridge status | doctor | logs | pair CODE | update | uninstall
    #
    # Homebrew puts only the installer here: the package Seayora signed, still
    # packed. The first run unpacks it as root into a new folder of its own and
    # runs its installer, which checks every file against Seayora's signature and
    # installs the bridge as a service. From then on this command hands everything
    # to the bridge's own command, seayora-bridge.
    #
    # Every way out of main is exec or exit. On an Intel Mac this file IS
    # /usr/local/bin/seabridge, and the installer writes the bridge's own command
    # over it while it runs; a shell reads its script as it goes, so this one must
    # never read another line once the installer starts.

    PACKAGE='@PACKAGE@'

    usage() {
        echo 'Seayora Bridge: connects the cameras and building equipment on this network to Seayora.'
        echo ''
        echo '  seabridge ABCD-2345       install it and pair it, with the code Seayora shows you'
        echo '                            (Cameras, then Bridges, then Add a bridge)'
        echo '  seabridge --pair-later    install it now; pair it later: seabridge pair ABCD-2345'
        echo ''
        echo 'It asks for your password: the bridge runs as a service that starts with the computer.'
        echo 'Afterwards: seabridge status | doctor | logs | update | uninstall'
        echo 'Guide: https://seayora.com/docs/security-cameras'
    }

    # The bridge's own command, once it is installed (its installer writes it).
    installed() {
        for f in /usr/local/bin/seayora-bridge /usr/bin/seayora-bridge; do
            if [ -x "$f" ] && grep -q 'Written by the Seayora Bridge installer' "$f" 2>/dev/null; then
                echo "$f"
                return 0
            fi
        done
        return 1
    }

    as_root() {
        if [ "$(id -u)" = 0 ]; then exec "$@"; fi
        if ! command -v sudo >/dev/null 2>&1; then
            echo 'seabridge: run this as root; sudo is not installed.' >&2
            exit 1
        fi
        exec sudo "$@"
    }

    # Unpack the package into a folder only root can write, run its installer and
    # remove the folder. Linux unpacks under /var/lib: /tmp and /var/tmp are often
    # mounted noexec, and the installer runs Node.js from the folder.
    install_bridge() {
        if [ ! -f "$PACKAGE" ]; then
            echo "seabridge: the package is missing ($PACKAGE). Run: brew reinstall seabridge" >&2
            exit 1
        fi
        as_root /bin/sh -c '
            set -eu
            case "$(uname -s)" in Darwin) base=/private/tmp ;; *) base=/var/lib ;; esac
            dir=$(mktemp -d "$base/seayora-bridge-setup.XXXXXX")
            cleanup() { rm -rf "$dir"; }
            trap cleanup EXIT INT TERM
            tar -xzf "$0" -C "$dir"
            installer=""
            for i in "$dir"/*/install; do installer=$i; done
            if [ ! -f "$installer" ]; then
                echo "seabridge: the package has no installer in it. Run: brew reinstall seabridge" >&2
                exit 1
            fi
            "$installer" "$@"
        ' "$PACKAGE" "$@"
    }

    main() {
        case "${1:-}" in
            -h|--help|help) usage; exit 0 ;;
            install) shift; install_bridge "$@" ;;
        esac
        if cli=$(installed); then as_root "$cli" "$@"; fi
        install_bridge "$@"
    }

    main "$@"
  SH

  def install
    libexec.install Dir["seayora-bridge-*.tar.gz"].first => "seayora-bridge.tar.gz"
    (bin/"seabridge").write WRAPPER.gsub("@PACKAGE@", (opt_libexec/"seayora-bridge.tar.gz").to_s)
    chmod 0755, bin/"seabridge"
  end

  def caveats
    <<~EOS
      Install the bridge and pair it, with the code Seayora shows you
      (Cameras, then Bridges, then Add a bridge):
        seabridge ABCD-2345
      It asks for your password and installs a service that starts with the computer.
      The bridge keeps itself up to date; brew upgrade only refreshes this installer.
      brew uninstall removes only the installer. To remove the bridge: seabridge uninstall
    EOS
  end

  test do
    assert_match "seabridge ABCD-2345", shell_output("#{bin}/seabridge --help")
    assert_match %r{/install$}, shell_output("tar -tzf #{libexec}/seayora-bridge.tar.gz")
  end
end
